{
  "requirement_id": "REQ-009",
  "cases": [
    {
      "id": "TC-1",
      "title": "Case-insensitive substring search on task titles",
      "surface": "api",
      "steps": [
        "GET /api/projects/1/tasks?q=login with header X-User: alice"
      ],
      "expected": "Search must be case-insensitive (ASCII), e.g., q=login should match 'Fix Login Bug'."
    },
    {
      "id": "TC-2",
      "title": "Literal treatment of '%' and '_' characters in search queries",
      "surface": "api",
      "steps": [
        "GET /api/projects/1/tasks?q=50%_complete with header X-User: alice"
      ],
      "expected": "Characters '%' and '_' must be treated as normal characters without acting as wildcards."
    },
    {
      "id": "TC-3",
      "title": "Combination of search query with status filter and pagination",
      "surface": "api",
      "steps": [
        "GET /api/projects/1/tasks?q=Bug&status=todo&limit=10&offset=0 with header X-User: alice"
      ],
      "expected": "The search query can be used simultaneously with the 'status' filter and pagination."
    }
  ]
}

